const WSOL = "So11111111111111111111111111111111111111112";

// Pull validated bot config
const botConfig = $node["Validate Bot Config"]?.json ?? {};

const pairAddressInput = botConfig?.pairAddress ?? null;

// Pull RPC responses
const splResp = $node["Vaults SPL"]?.json ?? {};
const t22Resp = $node["Vaults Token2022"]?.json ?? {};

const splErr = splResp?.error ?? null;
const t22Err = t22Resp?.error ?? null;

const spl = splResp?.result?.value ?? [];
const t22 = t22Resp?.result?.value ?? [];

const all = [...spl, ...t22];

// Normalize token accounts
const norm = all
  .map((a) => {
    const info = a?.account?.data?.parsed?.info ?? {};
    const ta = info?.tokenAmount ?? {};

    return {
      pubkey: a?.pubkey ?? null,
      mint: info?.mint ?? null,
      owner: info?.owner ?? null,
      uiAmount: Number(ta?.uiAmountString ?? ta?.uiAmount ?? 0)
    };
  })
  .filter((x) => x.pubkey && x.mint);

// Deduplicate by token account pubkey
const map = new Map();

for (const x of norm) {
  map.set(x.pubkey, x);
}

const uniq = [...map.values()];

// Find SOL vault
const solVault = uniq.find((x) => x.mint === WSOL) ?? null;

// Pick largest non-SOL token account as meme vault
const nonSol = uniq
  .filter((x) => x.mint !== WSOL)
  .sort((a, b) => b.uiAmount - a.uiAmount);

const memeVault = nonSol[0] ?? null;

const ok = !!solVault && !!memeVault && !splErr && !t22Err;

return [{
  json: {
    ok,

    // ------------------------------------------------------------
    // Carry forward bot config
    // ------------------------------------------------------------
    label: botConfig?.label ?? null,

    pairAddressInput,
    pairAddress: pairAddressInput,

    botWalletPublicKey: botConfig?.botWalletPublicKey ?? null,

    startingBankrollUsd: botConfig?.startingBankrollUsd ?? null,
    resetPortfolio: botConfig?.resetPortfolio ?? false,

    buyUsd: botConfig?.buyUsd ?? null,
    targetProfitUsd: botConfig?.targetProfitUsd ?? null,
    stopLossUsd: botConfig?.stopLossUsd ?? null,

    activeTrading: botConfig?.activeTrading ?? false,
    mode: botConfig?.mode ?? "paper",

    // ------------------------------------------------------------
    // RPC debug info
    // ------------------------------------------------------------
    rpcErrors: {
      spl: splErr,
      token2022: t22Err
    },

    counts: {
      splCount: spl.length,
      token2022Count: t22.length,
      totalUnique: uniq.length
    },

    // ------------------------------------------------------------
    // Discovered vaults/mints
    // ------------------------------------------------------------
    solVaultTokenAccount: solVault?.pubkey ?? null,
    solMint: solVault?.mint ?? null,

    memeVaultTokenAccount: memeVault?.pubkey ?? null,
    memeMint: memeVault?.mint ?? null,

    allTokenAccounts: uniq,

    note:
      (!pairAddressInput)
        ? "pairAddress missing from Validate Bot Config."
        : (splErr || t22Err)
          ? "One HTTP node returned RPC error; check rpcErrors."
          : (!solVault)
            ? "SOL vault was not found."
            : (!memeVault)
              ? "MEME vault was not found."
              : "Both vault token accounts found."
  }
}];

// ============================================================
// CALCULATE PRICE
// Reads getMultipleAccounts response from "Base and Quote Balance"
// and carries forward bot config from "Extract Vault Address".
// ============================================================

const resp = $json;

const snapshotSlot = resp?.result?.context?.slot ?? null;
const accounts = resp?.result?.value ?? [];

const memeAccount = accounts[0] ?? null;
const solAccount = accounts[1] ?? null;

const vaultInfo = $node["Extract Vault Address"]?.json ?? {};

const label = vaultInfo?.label ?? null;

const pairAddress = vaultInfo?.pairAddress ?? vaultInfo?.pairAddressInput ?? null;

const botWalletPublicKey = vaultInfo?.botWalletPublicKey ?? null;

const startingBankrollUsd = Number(vaultInfo?.startingBankrollUsd ?? 0);
const resetPortfolio = Boolean(vaultInfo?.resetPortfolio ?? false);

const buyUsd = Number(vaultInfo?.buyUsd ?? 0);
const targetProfitUsd = Number(vaultInfo?.targetProfitUsd ?? 0);
const stopLossUsd = Number(vaultInfo?.stopLossUsd ?? 0);

const activeTrading = Boolean(vaultInfo?.activeTrading ?? false);
const mode = String(vaultInfo?.mode ?? "paper");

const memeVaultTokenAccount = vaultInfo?.memeVaultTokenAccount ?? null;
const solVaultTokenAccount = vaultInfo?.solVaultTokenAccount ?? null;
const memeMint = vaultInfo?.memeMint ?? null;
const solMint = vaultInfo?.solMint ?? null;

function getTokenAmount(account) {
  const tokenAmount = account?.data?.parsed?.info?.tokenAmount;

  if (!tokenAmount) {
    return {
      ok: false,
      uiAmount: null,
      rawAmount: null,
      decimals: null,
      error: "Missing tokenAmount field"
    };
  }

  const uiAmount = Number(tokenAmount?.uiAmountString ?? tokenAmount?.uiAmount);
  const rawAmount = tokenAmount?.amount ?? null;
  const decimals = tokenAmount?.decimals ?? null;

  if (!Number.isFinite(uiAmount)) {
    return {
      ok: false,
      uiAmount: null,
      rawAmount,
      decimals,
      error: "uiAmount is not a valid number"
    };
  }

  return {
    ok: true,
    uiAmount,
    rawAmount,
    decimals,
    error: null
  };
}

// ============================================================
// VALIDATION
// ============================================================

if (!resp?.result) {
  return [{
    json: {
      ...vaultInfo,
      ok: false,
      stage: "calculate_price",
      error: "Invalid RPC response: missing result",
      rpcError: resp?.error ?? null,
      rawResponse: resp
    }
  }];
}

if (!Array.isArray(accounts) || accounts.length < 2) {
  return [{
    json: {
      ...vaultInfo,
      ok: false,
      stage: "calculate_price",
      error: "Invalid getMultipleAccounts response: expected at least 2 accounts",
      snapshotSlot,
      accountsReturned: accounts.length,
      rawResponse: resp
    }
  }];
}

if (!memeAccount || !solAccount) {
  return [{
    json: {
      ...vaultInfo,
      ok: false,
      stage: "calculate_price",
      error: "One or both vault accounts returned null",
      snapshotSlot,
      memeAccountExists: !!memeAccount,
      solAccountExists: !!solAccount,
      memeVaultTokenAccount,
      solVaultTokenAccount,
      rawAccounts: accounts
    }
  }];
}

const memeBalance = getTokenAmount(memeAccount);
const solBalance = getTokenAmount(solAccount);

if (!memeBalance.ok || !solBalance.ok) {
  return [{
    json: {
      ...vaultInfo,
      ok: false,
      stage: "calculate_price",
      error: "Could not parse token balances from vault accounts",
      snapshotSlot,
      memeBalance,
      solBalance,
      memeRaw: memeAccount,
      solRaw: solAccount
    }
  }];
}

const baseUi = memeBalance.uiAmount;
const quoteUi = solBalance.uiAmount;

if (baseUi <= 0 || quoteUi <= 0) {
  return [{
    json: {
      ...vaultInfo,
      ok: false,
      stage: "calculate_price",
      error: "Invalid reserve values: reserves must be greater than zero",
      snapshotSlot,
      baseReserveMEME: baseUi,
      quoteReserveSOL: quoteUi,
      memeBalance,
      solBalance
    }
  }];
}

// ============================================================
// PRICE CALCULATION
// ============================================================

const solPriceMeme = quoteUi / baseUi;

const sanity =
  Number.isFinite(solPriceMeme) &&
  solPriceMeme > 0;

const usdPriceMeme = null;

const targetValueUsd =
  Number.isFinite(buyUsd) && Number.isFinite(targetProfitUsd)
    ? buyUsd + targetProfitUsd
    : null;

// ============================================================
// OUTPUT
// ============================================================

return [{
  json: {
    ok: sanity,
    stage: "calculate_price",

    label,

    pairAddress,
    botWalletPublicKey,

    startingBankrollUsd,
    resetPortfolio,

    buyUsd,
    targetProfitUsd,
    targetValueUsd,
    stopLossUsd,

    activeTrading,
    mode,

    pair: "MEME/SOL",

    memeMint,
    solMint,

    memeVaultTokenAccount,
    solVaultTokenAccount,

    solPriceMeme,
    usdPriceMeme,

    baseReserveMEME: baseUi,
    quoteReserveSOL: quoteUi,

    baseRawAmount: memeBalance.rawAmount,
    quoteRawAmount: solBalance.rawAmount,
    baseDecimals: memeBalance.decimals,
    quoteDecimals: solBalance.decimals,

    snapshotSlot,

    baseSlot: snapshotSlot,
    quoteSlot: snapshotSlot,

    timestamp: new Date().toISOString(),

    note: sanity
      ? "Price computed from MEME and SOL vault balances in one getMultipleAccounts snapshot."
      : "Price calculation failed sanity check. Verify vault accounts and token order."
  }
}];

// ============================================================
// PAPER TRADE NODE
// Shared bankroll version.
// Opens/updates one paper position per pair using shared cash.
// Does NOT close positions; exit/close happens in Store Exit node.
// ============================================================

const calc = $json;

const currentSolPerMeme = Number(calc?.solPriceMeme);

if (!Number.isFinite(currentSolPerMeme) || currentSolPerMeme <= 0) {
  return [{
    json: {
      ...calc,
      ok: false,
      stage: "paper_trade",
      error: "Invalid solPriceMeme from Calculate price"
    }
  }];
}

// ============================================================
// CONFIG
// ============================================================

const STARTING_BANKROLL_USD = Number(calc?.startingBankrollUsd ?? 100);
const RESET_PORTFOLIO = Boolean(calc?.resetPortfolio ?? false);

const CONFIG_BUY_USD = Number(calc?.buyUsd ?? 1);
const CONFIG_TARGET_PROFIT_USD = Number(calc?.targetProfitUsd ?? 2);
const CONFIG_STOP_LOSS_USD = Number(calc?.stopLossUsd ?? 1);

const SOL_USD = Number(calc.currentSolUsd);

if (!Number.isFinite(SOL_USD) || SOL_USD <= 0) {
  return [{
    json: {
      ...calc,
      ok: false,
      stage: "paper_trade",
      error: "Missing or invalid currentSolUsd before Paper Trade"
    }
  }];
}

if (!Number.isFinite(STARTING_BANKROLL_USD) || STARTING_BANKROLL_USD <= 0) {
  return [{
    json: {
      ...calc,
      ok: false,
      stage: "paper_trade",
      error: "Invalid startingBankrollUsd"
    }
  }];
}

if (!Number.isFinite(CONFIG_BUY_USD) || CONFIG_BUY_USD <= 0) {
  return [{
    json: {
      ...calc,
      ok: false,
      stage: "paper_trade",
      error: "Invalid buyUsd"
    }
  }];
}

if (!Number.isFinite(CONFIG_TARGET_PROFIT_USD) || CONFIG_TARGET_PROFIT_USD <= 0) {
  return [{
    json: {
      ...calc,
      ok: false,
      stage: "paper_trade",
      error: "Invalid targetProfitUsd"
    }
  }];
}

if (!Number.isFinite(CONFIG_STOP_LOSS_USD) || CONFIG_STOP_LOSS_USD <= 0) {
  return [{
    json: {
      ...calc,
      ok: false,
      stage: "paper_trade",
      error: "Invalid stopLossUsd"
    }
  }];
}

// Options: "no_fees", "low_fee", "realistic", "high_slippage"
const ACTIVE_SCENARIO_NAME = "low_fee";

// ============================================================
// FEE / SLIPPAGE SCENARIOS
// ============================================================

const SCENARIOS = [
  {
    name: "no_fees",
    description: "Original ideal paper trade. No fees, no slippage.",
    entrySwapFeePct: 0,
    exitSwapFeePct: 0,
    entrySlippagePct: 0,
    exitSlippagePct: 0,
    entryFixedFeeUsd: 0,
    exitFixedFeeUsd: 0
  },
  {
    name: "low_fee",
    description: "Small swap fee and small slippage.",
    entrySwapFeePct: 0.25,
    exitSwapFeePct: 0.25,
    entrySlippagePct: 0.50,
    exitSlippagePct: 0.50,
    entryFixedFeeUsd: 0.02,
    exitFixedFeeUsd: 0.02
  },
  {
    name: "realistic",
    description: "More realistic memecoin paper trade estimate.",
    entrySwapFeePct: 1.00,
    exitSwapFeePct: 1.00,
    entrySlippagePct: 2.00,
    exitSlippagePct: 2.00,
    entryFixedFeeUsd: 0.05,
    exitFixedFeeUsd: 0.05
  },
  {
    name: "high_slippage",
    description: "Stress test for thin liquidity / bad fill.",
    entrySwapFeePct: 1.00,
    exitSwapFeePct: 1.00,
    entrySlippagePct: 5.00,
    exitSlippagePct: 5.00,
    entryFixedFeeUsd: 0.25,
    exitFixedFeeUsd: 0.25
  }
];

// ============================================================
// STATIC STORAGE / PORTFOLIO INIT
// ============================================================

const store = $getWorkflowStaticData("global");

if (RESET_PORTFOLIO || !store.portfolio) {
  store.portfolio = {
    startingBankrollUsd: STARTING_BANKROLL_USD,
    cashUsd: STARTING_BANKROLL_USD,
    positions: {},
    createdAt: new Date().toISOString(),
    resetAt: RESET_PORTFOLIO ? new Date().toISOString() : null
  };

  store.highestPnLUsd = {};
  store.completedTrades = [];
}

store.portfolio.positions = store.portfolio.positions || {};
store.highestPnLUsd = store.highestPnLUsd || {};
store.completedTrades = store.completedTrades || {};

const portfolio = store.portfolio;

// Stable key per coin/pair
const key =
  calc?.pairAddress ||
  calc?.memeMint ||
  calc?.memeVaultTokenAccount ||
  "UNKNOWN_PAIR";

let pos = portfolio.positions[key] ?? null;

// If this pair was already closed, do not reopen automatically
if (pos?.status === "CLOSED") {
  return [{
    json: {
      ...calc,
      ok: true,
      stage: "paper_trade",

      currentPairKey: key,
      positionStatus: "CLOSED",
      positionOpened: false,
      skippedClosedPosition: true,

      portfolioCashUsd: portfolio.cashUsd,
      portfolioStartingBankrollUsd: portfolio.startingBankrollUsd,
      openPositionsCount: Object.values(portfolio.positions).filter(p => p.status === "OPEN").length,

      targetHit: false,
      stopLossHit: false,
      shouldExit: false,
      exitReason: "ALREADY_CLOSED",

      note: "This pair was already closed. Skipping automatic reopen."
    }
  }];
}

// Open position if none exists
if (!pos) {
  const availableCashUsd = Number(portfolio.cashUsd ?? 0);
  const tradeUsd = Math.min(CONFIG_BUY_USD, availableCashUsd);

  if (!Number.isFinite(tradeUsd) || tradeUsd <= 0) {
    return [{
      json: {
        ...calc,
        ok: true,
        stage: "paper_trade",

        currentPairKey: key,
        positionOpened: false,
        positionStatus: "NO_CASH",

        portfolioCashUsd: availableCashUsd,
        portfolioStartingBankrollUsd: portfolio.startingBankrollUsd,
        openPositionsCount: Object.values(portfolio.positions).filter(p => p.status === "OPEN").length,

        targetHit: false,
        stopLossHit: false,
        shouldExit: false,
        exitReason: "NO_CASH",

        note: "No available portfolio cash to open this position."
      }
    }];
  }

  const targetValueUsd = tradeUsd + CONFIG_TARGET_PROFIT_USD;

  portfolio.cashUsd = availableCashUsd - tradeUsd;

  pos = {
    status: "OPEN",

    pairAddress: calc?.pairAddress ?? null,
    memeMint: calc?.memeMint ?? null,

    configuredBuyUsd: CONFIG_BUY_USD,
    usdInput: tradeUsd,

    targetProfitUsd: CONFIG_TARGET_PROFIT_USD,
    targetValueUsd,
    stopLossUsd: CONFIG_STOP_LOSS_USD,

    entryPriceSolPerMeme: currentSolPerMeme,
    entrySolUsd: SOL_USD,
    entryTimestamp: new Date().toISOString()
  };

  portfolio.positions[key] = pos;
}

const usdInput = Number(pos.usdInput);
const targetProfitUsd = Number(pos.targetProfitUsd);
const targetValueUsd = Number(pos.targetValueUsd);
const stopLossUsd = Number(pos.stopLossUsd);

const entryPriceSolPerMeme = Number(pos.entryPriceSolPerMeme);
const entrySolUsd = Number(pos.entrySolUsd);
const currentSolUsd = SOL_USD;

if (
  !Number.isFinite(usdInput) ||
  !Number.isFinite(targetProfitUsd) ||
  !Number.isFinite(targetValueUsd) ||
  !Number.isFinite(stopLossUsd) ||
  !Number.isFinite(entryPriceSolPerMeme) ||
  !Number.isFinite(entrySolUsd) ||
  usdInput <= 0 ||
  targetProfitUsd <= 0 ||
  targetValueUsd <= 0 ||
  stopLossUsd <= 0 ||
  entryPriceSolPerMeme <= 0 ||
  entrySolUsd <= 0
) {
  return [{
    json: {
      ...calc,
      ok: false,
      stage: "paper_trade",
      error: "Invalid stored paper trade position",
      position: pos
    }
  }];
}

// ============================================================
// HELPERS
// ============================================================

function pctToDecimal(pct) {
  return Number(pct) / 100;
}

function simulateScenario(scenario) {
  const entrySwapFee = pctToDecimal(scenario.entrySwapFeePct);
  const exitSwapFee = pctToDecimal(scenario.exitSwapFeePct);
  const entrySlippage = pctToDecimal(scenario.entrySlippagePct);
  const exitSlippage = pctToDecimal(scenario.exitSlippagePct);

  const entryFixedFeeUsd = Number(scenario.entryFixedFeeUsd ?? 0);
  const exitFixedFeeUsd = Number(scenario.exitFixedFeeUsd ?? 0);

  const idealEntryUsdPerMeme = entryPriceSolPerMeme * entrySolUsd;

  const usdAfterEntryFixedFee = Math.max(0, usdInput - entryFixedFeeUsd);
  const usdAfterEntrySwapFee = usdAfterEntryFixedFee * (1 - entrySwapFee);

  const effectiveEntryUsdPerMeme = idealEntryUsdPerMeme * (1 + entrySlippage);

  const memeQty = usdAfterEntrySwapFee / effectiveEntryUsdPerMeme;

  const currentUsdPerMeme = currentSolPerMeme * currentSolUsd;

  const grossCurrentValueUsd = memeQty * currentUsdPerMeme;

  const afterExitSlippageUsd = grossCurrentValueUsd * (1 - exitSlippage);
  const afterExitSwapFeeUsd = afterExitSlippageUsd * (1 - exitSwapFee);

  const estimatedExitValueUsd = Math.max(0, afterExitSwapFeeUsd - exitFixedFeeUsd);

  const pnlUsd = estimatedExitValueUsd - usdInput;
  const pnlPct = (pnlUsd / usdInput) * 100;

  const rawPriceMovePct =
    ((currentSolPerMeme - entryPriceSolPerMeme) / entryPriceSolPerMeme) * 100;

  return {
    name: scenario.name,
    description: scenario.description,

    assumptions: {
      entrySwapFeePct: scenario.entrySwapFeePct,
      exitSwapFeePct: scenario.exitSwapFeePct,
      entrySlippagePct: scenario.entrySlippagePct,
      exitSlippagePct: scenario.exitSlippagePct,
      entryFixedFeeUsd,
      exitFixedFeeUsd
    },

    memeQty,

    idealEntryUsdPerMeme,
    effectiveEntryUsdPerMeme,
    currentUsdPerMeme,

    grossCurrentValueUsd,
    estimatedExitValueUsd,

    pnlUsd,
    pnlPct,
    rawPriceMovePct
  };
}

// ============================================================
// RUN SCENARIOS
// ============================================================

const scenarioResults = SCENARIOS.map(simulateScenario);

const activeScenario =
  scenarioResults.find(s => s.name === ACTIVE_SCENARIO_NAME) ||
  scenarioResults.find(s => s.name === "no_fees") ||
  scenarioResults[0];

const currentPositionValue = activeScenario.estimatedExitValueUsd;
const moneyLostOrGained = activeScenario.pnlUsd;

// ============================================================
// EXIT LOGIC
// ============================================================

const targetHit = currentPositionValue >= targetValueUsd;
const profitTargetHit = moneyLostOrGained >= targetProfitUsd;

const stopLossHit = moneyLostOrGained <= -stopLossUsd;

const shouldExit = targetHit || stopLossHit;

const exitReason =
  targetHit
    ? "TAKE_PROFIT"
    : stopLossHit
      ? "STOP_LOSS"
      : "NONE";

// ============================================================
// TRACK HIGHEST PNL
// ============================================================

const highKey = `${key}:${activeScenario.name}`;

const prevHigh =
  typeof store.highestPnLUsd[highKey] === "number"
    ? store.highestPnLUsd[highKey]
    : null;

let highestPointUpdated = false;

if (prevHigh === null || moneyLostOrGained > prevHigh) {
  store.highestPnLUsd[highKey] = moneyLostOrGained;
  highestPointUpdated = true;
}

const highestPointUSD = store.highestPnLUsd[highKey];

const openPositionsCount =
  Object.values(portfolio.positions).filter(p => p.status === "OPEN").length;

// ============================================================
// OUTPUT
// ============================================================

return [{
  json: {
    ...calc,

    ok: true,
    stage: "paper_trade",

    currentPairKey: key,
    positionStatus: pos.status,
    positionOpened: true,

    activeScenario: activeScenario.name,

    configuredBuyUsd: pos.configuredBuyUsd,
    dollarAmountBought: usdInput,

    targetProfitUsd,
    targetValueUsd,

    stopLossUsd,
    stopLossValueUsd: usdInput - stopLossUsd,

    entryPriceSolPerMeme,
    currentPriceSolPerMeme: currentSolPerMeme,

    entrySolUsd,
    currentSolUsd,

    currentPositionValue,
    moneyLostOrGained,
    pnlPct: activeScenario.pnlPct,

    targetHit,
    profitTargetHit,
    stopLossHit,

    shouldExit,
    exitReason,

    highestPointUSD,
    previousHighestPointUSD: prevHigh,
    highestPointUpdated,

    portfolioStartingBankrollUsd: portfolio.startingBankrollUsd,
    portfolioCashUsd: portfolio.cashUsd,
    portfolioOpenPositionsCount: openPositionsCount,

    entryTimestamp: pos.entryTimestamp,
    currentTimestamp: new Date().toISOString(),

    scenarioResults,

    note: targetHit
      ? "Take-profit target hit. In live mode, this would move to sell logic."
      : stopLossHit
        ? "Stop loss hit. In live mode, this would move to sell logic."
        : "No exit condition hit. Continue monitoring."
  }
}];

// ============================================================
// VALIDATE BOT CONFIG
// Mode: Run Once for Each Item
// ============================================================

const pairAddress = String($json.pairAddress ?? "").trim();
const botWalletPublicKey = String($json.botWalletPublicKey ?? "").trim();

const startingBankrollUsd = Number($json.startingBankrollUsd ?? 0);
const resetPortfolio = Boolean($json.resetPortfolio ?? false);

const buyUsd = Number($json.buyUsd ?? 0);
const targetProfitUsd = Number($json.targetProfitUsd ?? 0);
const stopLossUsd = Number($json.stopLossUsd ?? 0);

const activeTrading = Boolean($json.activeTrading ?? false);
const mode = String($json.mode ?? "paper").trim();

const solanaAddressPattern = /^[1-9A-HJ-NP-Za-km-z]{32,44}$/;

const errors = [];

if (!solanaAddressPattern.test(pairAddress)) {
  errors.push("pairAddress is missing or does not look like a Solana address.");
}

if (!solanaAddressPattern.test(botWalletPublicKey)) {
  errors.push("botWalletPublicKey is missing or does not look like a Solana address.");
}

if (!Number.isFinite(startingBankrollUsd) || startingBankrollUsd <= 0) {
  errors.push("startingBankrollUsd must be a positive number.");
}

if (!Number.isFinite(buyUsd) || buyUsd <= 0) {
  errors.push("buyUsd must be a positive number.");
}

if (!Number.isFinite(targetProfitUsd) || targetProfitUsd <= 0) {
  errors.push("targetProfitUsd must be a positive number.");
}

if (!Number.isFinite(stopLossUsd) || stopLossUsd <= 0) {
  errors.push("stopLossUsd must be a positive number.");
}

if (!["paper", "live"].includes(mode)) {
  errors.push("mode must be either 'paper' or 'live'.");
}

if (errors.length > 0) {
  return {
    json: {
      ...$json,
      ok: false,
      stage: "validate_bot_config",
      errors,
      note: "Config has errors. Fix before continuing."
    }
  };
}

return {
  json: {
    ...$json,

    ok: true,
    stage: "validate_bot_config",

    pairAddress,
    botWalletPublicKey,

    startingBankrollUsd,
    resetPortfolio,

    buyUsd,
    targetProfitUsd,
    stopLossUsd,

    activeTrading,
    mode,

    note: activeTrading
      ? "Config valid, but activeTrading is true. Be careful."
      : "Config valid. Trading is disabled for now."
  }
};

// ============================================================
// ATTACH SOL PRICE
// Parses SOL/USD from Dexscreener response
// and merges it back into Calculate price output.
// ============================================================

// Original MEME/SOL price data
const calc = $node["Calculate price"].json;

// All incoming items from Sol Price HTTP node
const items = $input.all();

// Dexscreener may return:
// 1. one item containing an array
// 2. multiple items, one pair per item
let pairs = [];

if (items.length === 1 && Array.isArray(items[0].json)) {
  pairs = items[0].json;
} else if (items.length === 1 && Array.isArray(items[0].json?.pairs)) {
  pairs = items[0].json.pairs;
} else {
  pairs = items.map(item => item.json);
}

if (!Array.isArray(pairs) || pairs.length === 0) {
  return [{
    json: {
      ...calc,
      ok: false,
      stage: "attach_sol_price",
      error: "No SOL price pairs returned from Dexscreener",
      rawSolPriceResponse: items.map(i => i.json)
    }
  }];
}

// Pick the pair with highest liquidity
const sorted = [...pairs].sort((a, b) => {
  const la = Number(a?.liquidity?.usd ?? 0);
  const lb = Number(b?.liquidity?.usd ?? 0);
  return lb - la;
});

const best = sorted[0];

const currentSolUsd = Number(best?.priceUsd);

if (!Number.isFinite(currentSolUsd) || currentSolUsd <= 0) {
  return [{
    json: {
      ...calc,
      ok: false,
      stage: "attach_sol_price",
      error: "Could not parse SOL/USD price",
      selectedPair: best,
      rawSolPriceResponse: items.map(i => i.json)
    }
  }];
}

// Convert MEME/SOL price into MEME/USD
const usdPriceMeme =
  Number.isFinite(Number(calc.solPriceMeme))
    ? Number(calc.solPriceMeme) * currentSolUsd
    : null;

return [{
  json: {
    ...calc,

    ok: true,
    stage: "attach_sol_price",

    currentSolUsd,
    usdPriceMeme,

    solUsdPriceSource: "dexscreener",
    solUsdSelectedPairAddress: best?.pairAddress ?? null,
    solUsdSelectedDexId: best?.dexId ?? null,
    solUsdLiquidityUsd: best?.liquidity?.usd ?? null,
    solUsdUpdatedAt: new Date().toISOString(),

    note: "SOL/USD attached. Ready for Paper Trade."
  }
}];

// ============================================================
// STORE EXIT / WOULD SELL
// Runs when take-profit or stop-loss is hit.
// Closes paper position and returns value to shared bankroll.
// ============================================================

const trade = $json;

const store = $getWorkflowStaticData("global");

store.portfolio = store.portfolio || {
  startingBankrollUsd: Number(trade.portfolioStartingBankrollUsd ?? trade.startingBankrollUsd ?? 100),
  cashUsd: Number(trade.portfolioCashUsd ?? 0),
  positions: {}
};

store.portfolio.positions = store.portfolio.positions || {};
store.completedTrades = store.completedTrades || [];

const key =
  trade.currentPairKey ||
  trade.pairAddress ||
  trade.memeMint ||
  trade.memeVaultTokenAccount ||
  "UNKNOWN_PAIR";

const pos = store.portfolio.positions[key] ?? null;

const finalProfitUsd = Number(trade.moneyLostOrGained ?? 0);
const finalProfitPct = Number(trade.pnlPct ?? 0);
const finalPositionValueUsd = Number(trade.currentPositionValue ?? 0);

const exitReason = trade.exitReason ?? (
  trade.targetHit ? "TAKE_PROFIT" :
  trade.stopLossHit ? "STOP_LOSS" :
  "UNKNOWN"
);

let cashCreditedUsd = 0;
let alreadyClosed = false;

if (pos && pos.status === "OPEN") {
  store.portfolio.cashUsd = Number(store.portfolio.cashUsd ?? 0) + finalPositionValueUsd;

  pos.status = "CLOSED";
  pos.exitReason = exitReason;
  pos.exitTimestamp = new Date().toISOString();
  pos.finalPositionValueUsd = finalPositionValueUsd;
  pos.finalProfitUsd = finalProfitUsd;
  pos.finalProfitPct = finalProfitPct;

  cashCreditedUsd = finalPositionValueUsd;
} else if (pos && pos.status === "CLOSED") {
  alreadyClosed = true;
}

const completedTrade = {
  exitReason,

  pairAddress: trade.pairAddress ?? null,
  memeMint: trade.memeMint ?? null,
  botWalletPublicKey: trade.botWalletPublicKey ?? null,

  buyUsd: Number(trade.dollarAmountBought ?? trade.buyUsd ?? 0),
  configuredBuyUsd: Number(trade.configuredBuyUsd ?? trade.buyUsd ?? 0),

  targetProfitUsd: Number(trade.targetProfitUsd ?? 0),
  targetValueUsd: Number(trade.targetValueUsd ?? 0),
  stopLossUsd: Number(trade.stopLossUsd ?? 0),

  finalPositionValueUsd,
  finalProfitUsd,
  finalProfitPct,

  cashCreditedUsd,
  portfolioCashUsdAfterExit: store.portfolio.cashUsd,
  portfolioStartingBankrollUsd: store.portfolio.startingBankrollUsd,

  entryPriceSolPerMeme: trade.entryPriceSolPerMeme ?? null,
  finalPriceSolPerMeme: trade.currentPriceSolPerMeme ?? trade.solPriceMeme ?? null,

  entrySolUsd: trade.entrySolUsd ?? null,
  finalSolUsd: trade.currentSolUsd ?? null,

  activeScenario: trade.activeScenario ?? null,
  entryTimestamp: trade.entryTimestamp ?? null,
  exitSignalTimestamp: new Date().toISOString(),

  action: exitReason === "STOP_LOSS"
    ? "WOULD_SELL_STOP_LOSS"
    : "WOULD_SELL_TAKE_PROFIT",

  mode: trade.mode ?? "paper",
  activeTrading: trade.activeTrading ?? false
};

if (!alreadyClosed) {
  store.completedTrades.push(completedTrade);
}

if (store.completedTrades.length > 50) {
  store.completedTrades = store.completedTrades.slice(-50);
}

const openPositionsCount =
  Object.values(store.portfolio.positions).filter(p => p.status === "OPEN").length;

return [{
  json: {
    ...trade,

    ok: true,
    stage: "store_exit_would_sell",
    halted: true,

    action: completedTrade.action,
    exitReason,

    alreadyClosed,
    cashCreditedUsd,

    reason: alreadyClosed
      ? "Position was already closed. No cash credited again."
      : exitReason === "STOP_LOSS"
        ? "Stop loss hit. Exit snapshot stored and value returned to shared bankroll."
        : "Take-profit target hit. Exit snapshot stored and value returned to shared bankroll.",

    finalProfitUsd,
    finalProfitPct,
    finalPositionValueUsd,

    portfolioCashUsd: store.portfolio.cashUsd,
    portfolioStartingBankrollUsd: store.portfolio.startingBankrollUsd,
    portfolioOpenPositionsCount: openPositionsCount,

    completedTrade,
    completedTradesStored: store.completedTrades.length,

    timestamp: new Date().toISOString()
  }
}];

